import{_ as i,o as t,c as a,a2 as s}from"./chunks/framework.BiXHgXAn.js";const p=JSON.parse(`{"title":"Incident Response Plan","description":"Task's process for detecting, triaging, mitigating, and disclosing security incidents","frontmatter":{"title":"Incident Response Plan","description":"Task's process for detecting, triaging, mitigating, and disclosing security incidents","section":"Project","docType":"project","outline":"deep"},"headers":[],"relativePath":"docs/security/incident-response-plan.md","filePath":"next/docs/security/incident-response-plan.md"}`),o={name:"docs/security/incident-response-plan.md"};function n(r,e,l,c,d,u){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="incident-response-plan" tabindex="-1">Incident Response Plan <a class="header-anchor" href="#incident-response-plan" aria-label="Permalink to &quot;Incident Response Plan&quot;">​</a></h1><p>This document outlines our incident response plan in the event that a vulnerability is reported to the Task project. This serves as a high-level, public guide and is published as part of our commitment to transparency.</p><p>Below are the security principles that we aim to adhere to as a project:</p><ul><li><strong>Transparency</strong>: All incidents and fixes are documented here for the community.</li><li><strong>Stewardship</strong>: Take responsibility for protecting users and the project.</li><li><strong>Protection</strong>: Act to minimize harm and provide guidance.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>This plan applies to the core Task repository and all <em>official</em> Task projects. For example, the Visual Studio Code extension and officially supported installation methods. In the event that a vulnerability is reported with a community-managed installation method, we will work with the community and make a &quot;best-effort&quot; attempt to help resolve the issue.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="🔍-1-detect" tabindex="-1">🔍 1. Detect <a class="header-anchor" href="#🔍-1-detect" aria-label="Permalink to &quot;🔍 1. Detect&quot;">​</a></h3><ul><li>All security issues should be <strong>privately reported</strong> as described in our <a href="./">security documentation</a>.</li><li>Maintainers should also regularly monitor and respond to: <ul><li>Pull requests from dependency scanners such as Dependabot.</li><li>GitHub notifications and vulnerability alerts.</li><li>Messages in community channels such as Discord.</li></ul></li></ul><h3 id="🩺-2-triage" tabindex="-1">🩺 2. Triage <a class="header-anchor" href="#🩺-2-triage" aria-label="Permalink to &quot;🩺 2. Triage&quot;">​</a></h3><ul><li>Upon first receipt of a security issue, one of our team will immediately notify the other maintainers via a secure and private channel. This ensures that all maintainers are able to contribute to the issue where possible.</li><li>A maintainer should respond to the reporter in a timely manner in order to acknowledge receipt of the issue.</li><li>The issue must then be triaged into one of the following categories: <ul><li>‼️<strong>Critical</strong>: Has a serious and immediate impact on users or affects critical infrastructure related to the project.</li><li>❗<strong>High</strong>: Has the potential to seriously impact users of a distributed asset.</li><li>🟰<strong>Medium</strong>: Has the potential to impact users, but is obscure or low-risk.</li><li>➖<strong>Low</strong>: No direct or immediate impact to users, but requires attention.</li></ul></li><li>Open a draft <a href="https://github.com/go-task/task/security/advisories" target="_blank" rel="noreferrer">GitHub Security Advisory (GHSA)</a> in the Task repository. <ul><li>Optionally create a CVE. This can be skipped for low/medium impact issues at the discretion of the maintainers.</li></ul></li></ul><h3 id="🩹-3-mitigate" tabindex="-1">🩹 3. Mitigate <a class="header-anchor" href="#🩹-3-mitigate" aria-label="Permalink to &quot;🩹 3. Mitigate&quot;">​</a></h3><ul><li>Act calmly and communicate decisions.</li><li>Stop the bleed. <ul><li>Before attempting to fix the issue, perform any actions that stop the problem from becoming worse. For example: <ul><li>Rotate any affected secrets.</li><li>Rebuild any affected services (website, etc.).</li></ul></li><li>It may be difficult to do some of this in cases where packages are maintained by the community if we are not yet ready to disclose the vulnerability publicly. This should be decided on a case-by-case basis.</li></ul></li><li>Address the root cause. <ul><li>Plan and document a fix.</li><li>Patch the issue.</li><li>Test the fix.</li><li>Release new versions.</li></ul></li></ul><h3 id="📢-4-disclose" tabindex="-1">📢 4. Disclose <a class="header-anchor" href="#📢-4-disclose" aria-label="Permalink to &quot;📢 4. Disclose&quot;">​</a></h3><ul><li>Publish the GitHub Security Advisory (GHSE). Make sure to include: <ul><li>The affected version(s)/services.</li><li>The impact of the issue.</li><li>The root cause.</li><li>The steps taken to resolve.</li></ul></li><li>Optionally, create a blog post and/or share the information via our socials and public communication channels.</li></ul><h3 id="🧠-5-learn" tabindex="-1">🧠 5. Learn <a class="header-anchor" href="#🧠-5-learn" aria-label="Permalink to &quot;🧠 5. Learn&quot;">​</a></h3><ul><li>Document the disclosure in a permanent location.</li><li>Make and document any changes that can be made to prevent similar issues from arising in the future.</li></ul>',17)])])}const m=i(o,[["render",n]]);export{p as __pageData,m as default};
